var n=`0534-mandi`;var a=`world-0534`;var t=`SA`;var o=`western-asia`;var r=4;var s=327;var d={en:`Mandi`,ua:`Манді`};var u={en:`A traditional dish from Saudi Arabia, centered on lamb, plain yogurt, lemon juice, basmati rice. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Саудівська Аравія. Основні складники: ягнятина, натуральний йогурт, лимонний сік, рис басматі. Домашній варіант із кількостями продуктів за етапами приготування.`};var g=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 150 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 150 хвилин.`,t:[`marinating`],m:150,i:[[`lamb`,850,`g`],[`plain-yogurt`,180,`g`],[`lemon-juice`,50,`ml`],[`ground-cumin`,5,`g`],[`ground-cardamom`,4,`g`]]},{en:`Roast in a preheated 190°C oven for about 145 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 145 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:145,i:[]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 28 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 28 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:28,i:[[`basmati-rice`,460,`g`],[`water`,1e3,`ml`],[`saffron-threads`,.3,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`raisin`,100,`g`]]}];var m={slug:n,id:a,country:`SA`,region:o,servings:4,minutes:327,title:d,text:u,steps:g};export{t as country,m as default,a as id,s as minutes,o as region,r as servings,n as slug,g as steps,u as text,d as title};